/* Standalone Founder OS. Calculator code and its storage are strictly read-only. */
(async function () {
  'use strict';
  const E = window.FounderEngine, A = window.FounderAdapter, B = window.FounderBridge;
  const root = document.getElementById('tab-ceo');
  if (!E || !A || !B || !root) return;
  const demo = ['localhost','127.0.0.1',''].includes(location.hostname) && new URLSearchParams(location.search).get('demo') === '1';
  const cloudMode=!demo&&!!window.FOUNDER_CLOUD_URL;
  let bridge, S, connection, formDirty=false, polling=false, saving=false;
  try{
    if(!demo&&location.hostname==='brzotomas.github.io'&&!cloudMode)throw new Error('Nepodařilo se načíst připojení ke společným datům. Obnov stránku');
    if(cloudMode){
      const token=window.FounderCloud.accessToken(location.hash,sessionStorage,'founder-cloud-access');
      if(!token){root.innerHTML='<div class="ceo-card"><h1>Founder OS</h1><p>Otevři osobní odkaz pro úpravy nebo sdílený odkaz pro náhled. Firemní údaje jsou dostupné jen přes přístupový odkaz.</p><p>Odkaz pro parťáka najde majitel po otevření aplikace pod tlačítkem Sdílet náhled.</p></div>';return;}
      root.textContent='Načítám aktuální firemní údaje…';
      bridge=window.FounderCloud.create({url:window.FOUNDER_CLOUD_URL,token,calculatorStorage:localStorage});
      await bridge.connect();
    }else bridge=B.create(demo?window.FounderDemo.createStorage():localStorage);
    connection=bridge.read();S=connection.state;
  }
  catch(error){root.textContent='Founder OS nemohl otevřít své úložiště: '+error.message+'. Kalkulačka nebyla změněna.';return;}
  const names = {DEMAND:'Poptávka',CONVERSION:'Konverze nabídek',CAPACITY:'Kapacita',ECONOMICS:'Ekonomika zakázek',CASH:'Peníze',DELIVERY:'Realizace a kvalita',DELIVERY_QUALITY:'Realizace a kvalita',PEOPLE:'Lidé',FOUNDER_LEVERAGE:'Čas zakladatele'};
  const confidence = {HIGH:'Vysoká jistota',MEDIUM:'Střední jistota',LOW:'Nízká jistota'};
  const statusText = {GREEN:'V pořádku',YELLOW:'Sledovat',RED:'Řešit',UNKNOWN:'Chybí data'};
  const verdicts = {DO:'Dává smysl',TEST:'Nejdřív malý test',WAIT:'Zatím nedělat',NEED_DATA:'Nejdřív doplnit data'};
  const escape = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const number = value => value == null || !Number.isFinite(value) ? '—' : new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:1}).format(value);
  const money = value => value == null || !Number.isFinite(value) ? 'Neznámé' : new Intl.NumberFormat('cs-CZ',{style:'currency',currency:'CZK',maximumFractionDigits:0}).format(value);
  const percent = value => value == null ? '—' : new Intl.NumberFormat('cs-CZ',{style:'percent',maximumFractionDigits:1}).format(value);
  const today = () => new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Prague'}).format(new Date());
  const dateLabel = value => {if(typeof value!=='string'||!value)return 'Bez data';const date=new Date(value.slice(0,10)+'T12:00:00');return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('cs-CZ').format(date):'Neplatné datum';};
  const clone = value => JSON.parse(JSON.stringify(value));
  const id = () => globalThis.crypto?.randomUUID?.() || Date.now().toString(36)+Math.random().toString(36).slice(2);
  let view='state', period='previous', decisionDraft={}, decisionResult=null, selectedJob='', reviewDraft={}, toastTimer;
  let input, state, plan;
  const data = () => A.ensure(S);
  const settings = () => ({...E.defaults(),...data().settings});
  const button = (label,action,primary=false,extra='') => `<button type="button" class="b ${primary?'prim':''}" data-ceo="${action}" ${extra}>${escape(label)}</button>`;
  const badge = (text,status='') => `<span class="ceo-badge ${escape(status)}">${escape(text)}</span>`;
  const list = values => `<ul>${(values||[]).map(x=>`<li>${escape(x)}</li>`).join('')}</ul>`;
  const row = (label,value,extra='') => `<div class="ceo-row ${extra}"><span>${escape(label)}</span><b>${escape(value)}</b></div>`;
  function field(label,name,value='',type='text',help='',attrs='') {
    return `<label class="ceo-field">${escape(label)}<input name="${name}" type="${type}" value="${escape(value)}" ${attrs}>${help?`<small>${escape(help)}</small>`:''}</label>`;
  }
  function area(label,name,value='',attrs='') { return `<label class="ceo-field ceo-full">${escape(label)}<textarea name="${name}" ${attrs}>${escape(value)}</textarea></label>`; }
  function select(label,name,value,options,help='') {return `<label class="ceo-field">${escape(label)}<select name="${name}">${options.map(([k,l])=>`<option value="${escape(k)}" ${String(k)===String(value)?'selected':''}>${escape(l)}</option>`).join('')}</select>${help?`<small>${escape(help)}</small>`:''}</label>`;}
  const numeric = (form,key,nullable=true) => {
    const raw=String(new FormData(form).get(key)??'').trim();
    if (!raw) return nullable?null:0;
    const result=Number(raw); if(!Number.isFinite(result)) throw new Error('Vyplň platnou číselnou hodnotu.'); return result;
  };
  const textValue = (form,key) => String(new FormData(form).get(key)??'').trim();
  function notify(message,error=false){const el=document.getElementById('ceo-toast');el.textContent=message;el.setAttribute('role',error?'alert':'status');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.textContent='',error?12000:5000);}
  async function persist(change) {
    if(saving)return false;
    saving=true;const controls=Array.from(root.querySelectorAll('input,select,textarea,button'),el=>[el,el.disabled]);controls.forEach(([el])=>el.disabled=true);
    try {await bridge.change(draft=>{S.founderOs=draft;change();});S=bridge.read().state;formDirty=false;return true;}
    catch(error){S=bridge.read().state;notify('Změna Founder OS se neuložila: '+error.message+' Kalkulačka nebyla změněna.',true);return false;}
    finally{saving=false;controls.forEach(([el,disabled])=>{if(el.isConnected)el.disabled=disabled;});}
  }
  function refresh(){
    connection=bridge.read();S=connection.state;
    const d=data();
    input=A.buildInput(S,{asOf:today(),period,sourceAvailable:connection.connected,planJob:z=>B.planJob(z,S.nastaveni)});
    if(!connection.connected){input.completedPaidJobs=null;const ownMetrics=['qualifiedLeads','availableHours','dailyAvailableHours','founderHours','founderDelegatableHours','understaffed','periodWeeks'];for(const key of Object.keys(input.metrics))if(!ownMetrics.includes(key))input.metrics[key]=null;input.dataIssues.unshift(cloudMode?'Zakázky zatím nejsou ve společném úložišti. Majitel je může připojit tlačítkem Připojit tuto kalkulačku nebo načíst JSON zálohu.':'Zdrojové zakázky kalkulačky nejsou v tomto prohlížeči dostupné. Načti její JSON zálohu nebo otevři Founder OS na stejné adrese jako kalkulačku.');}
    if(connection.mode==='import')input.dataIssues.unshift('Analýza používá ručně načtenou zálohu. Změny v kalkulačce se do této relace samy nepromítnou.');
    state=E.analyze(input,settings());plan=E.weeklyPlan(state);
    return d;
  }
  function cloudBar(){
    if(!cloudMode)return '';
    const c=connection,owner=c.role==='owner';
    const moment=x=>x?new Date(x).toLocaleString('cs-CZ'):'Zatím žádné';
    return '<div class="ceo-note"><b>'+ (owner?'Společná firma · úpravy':'Společná firma · náhled')+'</b><div id="ceo-sync-status" role="status">'+escape(c.lastError||('Uloženo: '+moment(c.savedAt)+' · Zakázky: '+moment(c.sourceSavedAt)))+'</div><div class="ceo-tools">'+button('Načíst aktuální','cloud-refresh')+(owner?button(c.attached?'Odpojit tuto kalkulačku':'Připojit tuto kalkulačku',c.attached?'cloud-detach':'cloud-attach')+button('Sdílet náhled','cloud-share')+button('Záloha neúspěšného uložení','cloud-draft'):'')+'</div><small>'+(owner&&c.attached?'Zakázky se aktualizují z tohoto prohlížeče, dokud je tato stránka otevřená.':'Zobrazené zakázky odpovídají poslednímu přenosu uvedenému výše.')+'</small></div>';
  }
  function render(){
    const d=refresh();
    root.innerHTML=`<div class="ceo-head"><div><div class="ceo-eyebrow">Demolice Morava / řízení firmy</div><h1>Founder OS</h1><p class="ceo-muted">Jedna priorita. Rozhodnutí podložená daty.</p></div><div class="ceo-tools"><label class="ceo-muted" for="ceo-period">Období</label><select id="ceo-period" class="ceo-select" style="width:auto"><option value="week" ${period==='week'?'selected':''}>Tento týden</option><option value="previous" ${period==='previous'?'selected':''}>Minulý týden</option><option value="4weeks" ${period==='4weeks'?'selected':''}>Poslední 4 týdny</option><option value="13weeks" ${period==='13weeks'?'selected':''}>Posledních 13 týdnů</option><option value="all" ${period==='all'?'selected':''}>Celá historie</option></select>${button('Data a cíle','settings')}</div></div>
      <div class="ceo-tabs" aria-label="Sekce Founder OS">${[['state','Stav firmy'],['constraint','Úzké hrdlo'],['cash','Cash a rezervy'],['decisions','Rozhodnutí'],['review','Týdenní review']].map(([key,label])=>`<button type="button" data-ceo="${key}" ${view===key?'aria-current="page"':''}>${label}</button>`).join('')}</div>
      ${demo?'<div class="ceo-note"><b>Vývojová ukázka · smyšlená data.</b> Všechny změny jsou jen v paměti této stránky. Žádná data kalkulačky ani Founder OS se neukládají.</div>':''}<div class="ceo-connection"><span>${demo?'Izolovaný testovací režim':connection.connected?(connection.mode==='shared'?'● Živě ze stejného prohlížeče · pouze čtení':'Načtená záloha · pouze tato relace'):'Kalkulačka zatím není připojená'}</span><div class="ceo-tools">${button('Načíst zálohu kalkulačky','import-source')}${connection.mode==='import'?button('Použít živá data','use-shared'):''}${button('Záloha Founder OS','backup')}</div></div>
      ${cloudBar()}<div id="ceo-content">${({state:stateView,constraint:constraintView,cash:cashView,decisions:decisionsView,review:reviewView,settings:settingsView})[view](d)}</div>`;
    if(cloudMode){
      const old=root.querySelector('.ceo-connection span');if(old)old.textContent=connection.connected?'Sdílené zakázky · kalkulačka pouze ke čtení':'Zakázky zatím nebyly připojené';
      if(connection.role!=='owner'){
        root.querySelectorAll('form input,form textarea,form select,form button,[data-ceo="import-source"],[data-ceo="restore-own"],[data-ceo="remove-flow"]').forEach(el=>el.disabled=true);
      }
    }
  }
  function issueNote(){const issues=[...new Set(state.dataIssues||[])];return issues.length?`<div class="ceo-note"><b>Spolehlivost závěru závisí na úplnosti dat.</b><details class="ceo-details"><summary>${issues.length} upozornění k datům</summary>${list(issues)}</details>${button('Doplnit chybějící údaje','settings')}</div>`:'';}
  function primaryBlock(){const p=state.primary;return `<div class="ceo-card ceo-primary"><div class="ceo-badges">${badge('FÁZE '+(state.stage.number??'—')+' · '+state.stage.label)}${badge(confidence[state.confidence]||'Nízká jistota')}</div><div class="ceo-eyebrow" style="margin-top:24px">Aktuální hlavní úzké hrdlo</div><h2>${p?escape(names[p.key]||p.key):'Nejdřív potřebujeme data'}</h2><p class="ceo-explain">${escape(p?.explanation||'Z dosud doložených údajů nelze poctivě vybrat jednu překážku růstu. Doplň cash, dostupnou kapacitu a výsledky zakázek.')}</p><div class="ceo-next"><div class="ceo-eyebrow">Jeden cíl pro tento týden</div><strong>${escape(plan.objective||p?.action||'Doplnit chybějící údaje a určit první prioritu.')}</strong><div class="ceo-actions">${button(p?'Proč právě tohle?':'Doplnit údaje',p?'constraint':'settings',true)}${button('Zahájit týdenní review','review')}</div></div><div class="ceo-stop"><b>Teď neřešit:</b> ${escape((p?.avoid||plan.avoid||['Velké závazky bez ověřené cash rezervy.']).slice(0,2).join(' · '))}</div></div>`;}
  function cashSummary(){return `<div class="ceo-card"><div class="ceo-eyebrow">Skutečně volné peníze</div><div class="ceo-cash-number ${state.cash.freeCash<0?'ceo-negative':''}">${money(state.cash.freeCash)}</div><p class="ceo-muted">Po odečtení závazků a provozní rezervy.</p><div class="ceo-rows">${row('Na účtu',money(state.cash.bankCash))}${row('Závazky + všechny rezervy',money(state.cash.reservedCash))}${row('Survival runway',number(state.cash.runway)+' týdnů')}</div>${button('Otevřít cash plán','cash')}<p class="ceo-muted">Stav k ${dateLabel(data().cash.asOf)}</p></div>`;}
  function stateView(){
    const m=state.metrics;
    return `<div class="ceo-grid"><div>${primaryBlock()}</div><aside>${cashSummary()}<div class="ceo-card"><div class="ceo-eyebrow">Fakta o firmě</div>${row('Dokončené a zaplacené',number(input.completedPaidJobs)+' zakázek')}${row('Zdroj dat','Uložené zakázky kalkulačky')}<p class="ceo-muted">${escape(input.period.label)}${input.period.partial?' · neúplné období':''}</p></div></aside></div>
      <div class="ceo-health">${['DEMAND','CONVERSION','CAPACITY','ECONOMICS','CASH','PEOPLE'].map(key=>{const c=state.constraints.find(x=>x.key===key);const s=c?.status||'UNKNOWN';return `<div class="ceo-health-item"><b>${escape(names[key])}</b>${badge(statusText[s]||'Chybí data',s)}</div>`;}).join('')}</div>
      <div class="ceo-metrics">${[['Kvalifikované poptávky',number(m.qualifiedLeads),'Z týdenních záznamů'],['Vyhrané / odeslané nabídky',percent(m.quoteWinRate),'Stejná kohorta nabídek'],['Vytížení kapacity',percent(m.utilization),'Prodané / dostupné osobohodiny'],['Hrubá marže',percent(m.grossMargin),'Tržby bez DPH − přímé náklady']].map(([label,value,help])=>`<div class="ceo-metric"><span>${label}</span><b>${value}</b><small>${help}</small></div>`).join('')}</div><div style="margin-top:20px">${issueNote()}</div>
      <details class="ceo-details"><summary>Další výpočty a jejich základ</summary><div class="ceo-card ceo-form"><div>${row('Tržby bez DPH',money(m.revenue))}${row('Skutečné přímé náklady',money(m.directCosts))}${row('Hrubý zisk',money(m.grossProfit))}${row('GP / člověkoden',money(m.gpPerCrewDay))}${row('Člověkodny (hodiny / pracovní den)',number(m.crewDays))}</div><div>${row('Odeslané nabídky',number(m.quotesSent))}${row('Vyhrané zakázky',number(m.jobsWon))}${row('Průměrná dokončená zakázka',money(m.averageTicket))}${row('Backlog',number(m.backlogDays)+' pracovních dní')}${row('Odchylka přímých nákladů',percent(m.costVariance))}</div></div></details>`;
  }
  function constraintView(){const p=state.primary;return `<div class="ceo-grid"><div>${primaryBlock()}${p?`<div class="ceo-card"><h2>Na čem diagnóza stojí</h2>${list(p.evidence)}<h3>Největší přínos teď má</h3><p>${escape(p.action)}</p><h3>Podmínka úspěchu</h3><p>${escape(p.success)}</p><h3>Co odložit</h3>${list(p.avoid)}</div>`:''}</div><aside><div class="ceo-card"><h2>Pořadí příčin</h2><p class="ceo-muted">Pravidla mají přednost před dojmem. Kritické cash riziko přebíjí ostatní signály.</p>${state.constraints.map(c=>`<div class="ceo-row"><span>${escape(names[c.key]||c.key)}<br><small>${confidence[c.confidence]||'Nízká jistota'}</small></span><div>${badge(c.score==null?'Neznámé':number(c.score)+' / 100',c.status||'UNKNOWN')}</div></div>`).join('')}</div><div class="ceo-note neutral">Skóre je nastavitelná heuristika, nikoli pravděpodobnost úspěchu. Chybějící údaj neznamená zdravou firmu.</div>${button('Upravit prahy pravidel','settings')}</aside></div>${issueNote()}<details class="ceo-details"><summary>Evidence všech kategorií</summary>${state.constraints.map(c=>`<div class="ceo-card"><h3>${escape(names[c.key]||c.key)}</h3><p>${escape(c.explanation)}</p>${list(c.evidence)}<p><b>Doporučení:</b> ${escape(c.action)}</p></div>`).join('')}</details>`;}
  function forecastChart(rows){
    const values=rows.flatMap(r=>[r.committed,r.expected]).filter(Number.isFinite);if(!values.length)return '';
    const lo=Math.min(0,...values),hi=Math.max(1,...values),range=hi-lo||1;
    const points=key=>rows.map((r,i)=>Number.isFinite(r[key])?`${10+i*55},${135-(r[key]-lo)/range*115}`:'').filter(Boolean).join(' ');
    return `<div class="ceo-forecast"><svg viewBox="0 0 680 155" role="img" aria-label="Vývoj zůstatku na příštích třináct týdnů; přesné částky jsou v tabulce níže"><line x1="10" x2="670" y1="${135-(0-lo)/range*115}" y2="${135-(0-lo)/range*115}" stroke="var(--line)"/><polyline points="${points('committed')}" fill="none" stroke="var(--accent)" stroke-width="3"/><polyline points="${points('expected')}" fill="none" stroke="var(--good)" stroke-dasharray="5 5" stroke-width="2"/></svg></div>`;
  }
  function cashView(d){
    const c=d.cash;
    const fc=E.forecast(state.cash,[...(input.cashItems||[]),...d.forecastItems],today(),settings());
    const rows=Array.isArray(fc)?fc:fc.weeks||[];
    return `<div class="ceo-grid"><div><div class="ceo-card"><h2>Kolik si můžeš dovolit investovat</h2><div class="ceo-cash-number ${state.cash.freeCash<0?'ceo-negative':''}">${money(state.cash.freeCash)}</div><div class="ceo-rows">${row('Bankovní zůstatek',money(c.bankCash))}${row('− DPH a daňové rezervy',money(c.taxReserve))}${row('− Závazné mzdy v rezervačním horizontu',money(c.payrollReserve))}${row('− Neuhrazení smluvní dodavatelé',money(c.committedPayables))}${row('− Neodpracované zálohy klientů',money(c.customerAdvanceReserve))}${row('− Minimální provozní rezerva',money(state.cash.operatingReserve))}${row('Volné k alokaci',money(state.cash.freeCash),'total')}</div><h3>Survival runway: ${number(state.cash.runway)} týdnů</h3><p class="ceo-muted">Při nulových nových příjmech. Zůstatek po daních, klientských zálohách a jednorázových dodavatelských závazcích dělený nezbytným týdenním výdajem. Pravidelné mzdy patří do týdenního výdaje.</p></div></div>
      <aside><div class="ceo-card"><h2>Aktualizovat cash snímek</h2><p class="ceo-muted">Vyplň jen samostatné rezervy. Daně a mzdy znovu nezahrnuj do dodavatelů. Z neodpracovaných záloh rezervuj pouze část, kterou už nekryje jiná rezerva. Prázdné pole = neznámé, nula = potvrzená nula.</p><form id="ceo-cash-form" class="ceo-form">${field('Stav k datu','asOf',c.asOf||today(),'date','',`max="${today()}" required`)}${field('Bankovní zůstatek (Kč)','bankCash',c.bankCash,'number','','step="0.01" required')}${field('DPH a daně (Kč)','taxReserve',c.taxReserve,'number','','min="0" step="0.01" required')}${field('Závazné mzdy (Kč)','payrollReserve',c.payrollReserve,'number','','min="0" step="0.01" required')}${field('Dodavatelské závazky (Kč)','committedPayables',c.committedPayables,'number','','min="0" step="0.01" required')}${field('Zálohy klientů k rezervování (Kč)','customerAdvanceReserve',c.customerAdvanceReserve,'number','','min="0" step="0.01" required')}${field('Nezbytné výdaje / týden (Kč)','weeklyBurn',c.weeklyBurn,'number','Včetně pravidelných mezd. Bez jednorázových závazků výše.','min="0" step="0.01" required')}${field('Závazky po splatnosti (Kč)','overdueLiabilities',c.overdueLiabilities,'number','Již jsou v rezervách výše; znovu se neodečítají.','min="0" step="0.01" required')}${select('Chybí peníze na prodanou práci?','unfundedWork',c.unfundedWork==null?'':String(c.unfundedWork),[['','Nevím'],['false','Ne'],['true','Ano']])}<div class="ceo-full"><button class="b prim" type="submit">Uložit a přepočítat</button></div></form></div></aside></div>
      <div class="ceo-card"><h2>Cashflow na 13 týdnů</h2><p class="ceo-muted">Potvrzená vrstva zahrnuje doložené příjmy a výdaje. Očekávaná vrstva přidává pravděpodobnostně vážené položky. Zůstatky v grafu jsou peníze na účtu, nikoli volná hotovost po rezervách.</p><div class="ceo-legend"><span>Potvrzené cashflow</span><span>Včetně očekávaného cashflow</span></div>${forecastChart(rows)}${fc.issues?.length?`<div class="ceo-note">${list(fc.issues)}</div>`:''}${fc.overdue?.length?`<div class="ceo-note"><b>${fc.overdue.length} položek je po termínu.</b> Nejsou automaticky považovány za přijaté či zaplacené. Uprav jejich splatnost v původní zakázce nebo cash plánu.</div>`:''}<div class="ceo-table"><table><thead><tr><th>Týden od</th><th class="r">Příjmy jisté</th><th class="r">Výdaje jisté</th><th class="r">Zůstatek potvrzený</th><th class="r">Zůstatek očekávaný</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${dateLabel(r.start)}</td><td class="r">${money(r.inflows)}</td><td class="r">${money(r.outflows)}</td><td class="r ${r.committed<0?'ceo-negative':''}">${money(r.committed)}</td><td class="r">${money(r.expected)}</td></tr>`).join('')}</tbody></table></div><p class="ceo-muted">Splatnosti záloh a doplatků se čtou ze zakázek. Níže doplň pouze chybějící plánované platby; již uhrazené výdaje se z účtu znovu neodečítají.</p></div>
      <div class="ceo-card"><h2>Chybějící plánovaná platba</h2><form id="ceo-forecast-form" class="ceo-form">${field('Popis','label','','text','','required maxlength="160"')}${field('Datum platby','date',today(),'date','','required')}${field('Částka (Kč)','amount','','number','','min="0.01" step="0.01" required')}${select('Směr','direction','out',[['out','Výdaj'],['in','Příjem']])}${select('Jistota platby','layer','committed',[['committed','Potvrzená / závazná'],['expected','Pouze očekávaná']])}${field('Pravděpodobnost 0–100 %','probability',100,'number','U potvrzené platby se vždy použije 100 %.','min="0" max="100" required')}${select('Kategorie','category','supplier',[['supplier','Dodavatelé'],['payroll','Mzdy a odvody'],['tax','Daně'],['rent','Nájem'],['capex','Technika a investice'],['other','Ostatní']])}<div class="ceo-full"><button class="b prim" type="submit">Přidat do plánu</button></div></form>${d.forecastItems.length?`<div class="ceo-table"><table><thead><tr><th>Položka</th><th>Datum</th><th>Vrstva</th><th class="r">Částka</th><th></th></tr></thead><tbody>${d.forecastItems.map(x=>`<tr><td>${escape(x.label)}</td><td>${dateLabel(x.date)}</td><td>${x.layer==='committed'?'Potvrzená':'Očekávaná'}</td><td class="r">${x.direction==='out'?'−':'+'}${money(x.amount)}</td><td>${button('Odebrat','remove-flow',false,`data-id="${escape(x.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:''}</div>${issueNote()}`;
  }

  // Remaining views keep form entry separate from the deterministic engine.
  function decisionsView(d){const x=decisionDraft;
    return `<div class="ceo-grid"><div class="ceo-card"><h2>Chci udělat rozhodnutí</h2><p class="ceo-muted">Nejprve ověř, zda řeší dnešní překážku růstu a jestli na něj firma má.</p><form id="ceo-decision-form" class="ceo-form">${field('Co chceš udělat?','title',x.title,'text','Například: otestovat brigádníka na pěti zakázkách.','required maxlength="180"')}${select('Typ rozhodnutí','type',x.type||'hiring',[['hiring','Nábor'],['marketing','Marketing'],['capex','Nákup techniky'],['expansion','Expanze'],['pricing','Ceny'],['service','Nová služba'],['software','Software'],['finance','Financování'],['other','Ostatní']])}${field('Jednorázový výdaj (Kč)','oneTimeCost',x.oneTimeCost??0,'number','','min="0" step="0.01" required')}${field('Nový měsíční výdaj (Kč)','monthlyCost',x.monthlyCost??0,'number','','min="0" step="0.01" required')}${field('Čas zakladatele (hodin)','founderHours',x.founderHours??0,'number','','min="0" step="0.5" required')}${field('Očekávané nové tržby / měsíc (Kč)','monthlyRevenueImpact',x.monthlyRevenueImpact,'number','Nech prázdné, pokud dopad neznáš.','min="0" step="0.01"')}${field('Očekávaná úspora / měsíc (Kč)','monthlySavings',x.monthlySavings,'number','','min="0" step="0.01"')}${field('Nová kapacita / měsíc (osobohodin)','capacityHours',x.capacityHours??0,'number','','min="0" step="0.5"')}${field('Za kolik dní získáš výsledek?','feedbackDays',x.feedbackDays??7,'number','','min="1" max="730" required')}${select('Vratnost rozhodnutí','reversibility',x.reversibility??3,[[5,'5 · snadno vratné'],[4,'4 · poměrně vratné'],[3,'3 · středně vratné'],[2,'2 · nákladný návrat'],[1,'1 · téměř nevratné']])}${select('Na čem stojí očekávání?','evidence',x.evidence||'guess',[['guess','Odhad / pocit'],['anecdotal','Jednotlivá zkušenost'],['test','Malý test'],['historical','Historická data firmy'],['strong','Silné opakované důkazy']])}${select('Jakou překážku to řeší?','targetConstraint',x.targetConstraint||'',[['','Zatím nevím'],...Object.entries(names).filter(([k])=>k!=='DELIVERY_QUALITY')])}${field('Která metrika se změní?','metric',x.metric,'text','','maxlength="180"')}${field('Jak to ověřit levněji?','cheaperTest',x.cheaperTest,'text','','maxlength="300"')}<div class="ceo-full"><button type="submit" class="b prim">Posoudit rozhodnutí</button></div></form></div><aside>${decisionResult?decisionOutput():`<div class="ceo-card"><div class="ceo-eyebrow">Kontext rozhodnutí</div><h2>${escape(state.primary?names[state.primary.key]||state.primary.key:'Hlavní překážka není doložená')}</h2>${row('Volné peníze',money(state.cash.freeCash))}${row('Runway',number(state.cash.runway)+' týdnů')}<p class="ceo-muted">Výsledek zohlední vztah k úzkému hrdlu, cash, návratnost, vratnost, rychlost ověření, důkazy i fázi firmy.</p></div>`}</aside></div><div class="ceo-card"><h2>Uložená rozhodnutí</h2>${d.decisions.length?d.decisions.slice().reverse().map(x=>`<details class="ceo-details"><summary>${escape(x.title)} · ${escape(verdicts[x.result?.verdict]||x.result?.verdict||'Uloženo')} · ${dateLabel(x.createdAt)}</summary><p>${escape((x.result?.reasons||[]).join(' '))}</p>${row('Volné cash po rozhodnutí',money(x.result?.remainingFreeCash))}<p class="ceo-muted">Historické hodnocení k datu uložení.</p></details>`).join(''):'<p class="ceo-muted">Zatím žádné rozhodnutí. Posouzení můžeš uložit po vyplnění formuláře.</p>'}</div>`;
  }
  function decisionOutput(){const r=decisionResult;return `<div class="ceo-card ceo-primary"><div class="ceo-eyebrow">Výsledek posouzení</div><h2>${escape(verdicts[r.verdict]||r.verdict)}</h2>${list(r.reasons)}${(r.flags||[]).map(f=>badge(f,'YELLOW')).join(' ')}<div class="ceo-rows">${row('Vztah k překážce',({YES:'Řeší',PARTLY:'Částečně',NO:'Neřeší',UNKNOWN:'Neznámý'})[r.constraintFit]||r.constraintFit)}${row('Vhodnost pro fázi firmy',({YES:'Vhodné',PARTLY:'Částečně',NO:'Předčasné',UNKNOWN:'Neznámé'})[r.stageFit]||r.stageFit)}${row('Volné peníze po rozhodnutí',money(r.remainingFreeCash))}${row('Runway před → po',number(r.runwayBefore)+' → '+number(r.runwayAfter)+' týdnů')}${row('Přírůstek měsíčního hrubého zisku',money(r.incrementalMonthlyGrossProfit))}${row('Návratnost',r.paybackMonths==null?'Nelze doložit':number(r.paybackMonths)+' měsíců')}</div><p class="ceo-muted">Dopad tržeb používá doloženou současnou marži. Je to scénář podle tvých očekávání, nikoli příslib výnosu.</p><h3>Lepší další krok</h3><p>${escape(r.betterMove)}</p><h3>Vrátit se k tomu, až</h3>${list(r.reconsider)}<div class="ceo-actions">${button('Uložit rozhodnutí','save-decision',true)}</div></div>`;}
  function reviewView(d){const r=reviewDraft;return `<div class="ceo-grid"><div class="ceo-card"><div class="ceo-eyebrow">10–15 minut / jednou týdně</div><h2>Týdenní CEO review</h2><p class="ceo-muted">Čísla se načetla ze zakázek. Doplň pouze zkušenosti, které v nich nejsou vidět.</p><form id="ceo-review-form" class="ceo-form">${area('Co se tento týden pokazilo?','wentWrong',r.wentWrong,'maxlength="3000"')}${area('Proč jsme podle tebe přišli o zakázky?','lostWhy',r.lostWhy,'maxlength="3000"')}${area('Co tě nejvíc brzdilo?','blockedBy',r.blockedBy,'required maxlength="3000"')}${area('Jaké překvapení jsme zjistili?','surprise',r.surprise,'maxlength="3000"')}${area('Co jsme testovali?','tested',r.tested,'maxlength="3000"')}${area('Co chceme udělat příští týden?','nextWeek',r.nextWeek,'required maxlength="3000"')}<div class="ceo-full"><button class="b prim" type="submit">Uzavřít review a uložit plán</button></div></form></div><aside><div class="ceo-card"><div class="ceo-eyebrow">Automaticky z dat</div><h2>${escape(state.stage.label)}</h2>${row('Hlavní překážka',state.primary?names[state.primary.key]||state.primary.key:'Nedostatek dat')}${row('Vytížení',percent(state.metrics.utilization))}${row('Konverze nabídek',percent(state.metrics.quoteWinRate))}${row('Hrubá marže',percent(state.metrics.grossMargin))}${row('Volné cash',money(state.cash.freeCash))}<h3>Jeden cíl</h3><p>${escape(plan.objective)}</p><h3>Maximálně tři kroky</h3>${list(plan.actions?.slice(0,3))}<h3>Odložit</h3>${list(plan.avoid)}<p class="ceo-muted">Uloží se neměnný snímek firmy i tehdejší pravidla. Pozdější změna dat jej nepřepíše.</p></div></aside></div>
      <div class="ceo-card"><h2>Jeden business experiment</h2><p>${escape(plan.experiment?.hypothesis||'Nejprve doplň údaje pro diagnózu.')}</p><form id="ceo-experiment-form" class="ceo-form">${field('Hypotéza','hypothesis',plan.experiment?.hypothesis,'text','','required maxlength="300"')}${field('Konkrétní akce','action',plan.experiment?.action,'text','','required maxlength="300"')}${field('Odpovědná osoba','owner','','text','','required maxlength="100"')}${field('Budget (Kč)','budget',plan.experiment?.budget??0,'number','','min="0" step="0.01" required')}${field('Začátek','startDate',today(),'date','','required')}${field('Konec','endDate','','date','','required')}${field('Hlavní metrika','metric',plan.experiment?.metric,'text','','required maxlength="180"')}${field('Číselný práh úspěchu','successThreshold',plan.experiment?.successValue,'number','','step="any" required')}${select('Úspěch znamená','comparison',plan.experiment?.comparison||'gte',[['gte','Výsledek alespoň tento práh'],['lte','Výsledek nejvýše tento práh']])}${area('Další podmínky úspěchu','conditions',plan.experiment?.successThreshold,'required maxlength="1200"')}<div class="ceo-full"><button type="submit" class="b prim" ${d.experiments.some(x=>x.status==='ACTIVE')?'disabled':''}>Zahájit jeden experiment</button></div></form>${d.experiments.some(x=>x.status==='ACTIVE')?'<p class="ceo-muted">Nejdřív vyhodnoť probíhající experiment, aby firma měla jednu prioritu.</p>':''}
      ${d.experiments.slice().reverse().map(x=>`<details class="ceo-details" ${x.status==='ACTIVE'?'open':''}><summary>${escape(x.hypothesis)} · ${escape(({ACTIVE:'Probíhá',VALIDATED:'Ověřeno',INVALIDATED:'Vyvráceno',INCONCLUSIVE:'Neprůkazné'})[x.status]||x.status)}</summary><p>${escape(x.action)} · ${escape(x.owner)} · ${dateLabel(x.startDate)}–${dateLabel(x.endDate)}</p><p><b>Další podmínky:</b> ${escape(x.conditions||'Nejsou zaznamenané; nelze potvrdit úspěch bez jejich ověření.')}</p>${row('Budget',money(x.budget))}${row('Úspěch',x.metric+' '+(x.comparison==='lte'?'≤':'≥')+' '+number(x.successThreshold))}${x.status==='ACTIVE'?`<form class="ceo-result-form ceo-form" data-id="${escape(x.id)}">${field('Naměřený výsledek','result','','number','','step="any"')}${select('Byly splněny i další podmínky?','conditionsMet','',[['','Neověřeno'],['true','Ano, všechny'],['false','Ne']])}${area('Co jsme zjistili a jaké je rozhodnutí?','decision','','required maxlength="1500"')}<div class="ceo-full"><button class="b prim" type="submit">Vyhodnotit experiment</button><p class="ceo-muted">Bez čísla nebo bez ověření dalších podmínek zůstane výsledek neprůkazný.</p></div></form>`:`<p><b>Výsledek:</b> ${number(x.result)}. ${escape(x.decision)}</p>`}</details>`).join('')}</div>
      <div class="ceo-card"><h2>Business memory</h2><p class="ceo-muted">Historie rozhodnutí, týdenních snímků a výsledků. ${cloudMode?'Uložené záznamy jsou společné pro všechny s přístupovým odkazem. Zálohu si můžeš stáhnout.':'Ukládá se do vlastní zálohy Founder OS v tomto prohlížeči.'}</p>${d.memory.length?`<div class="ceo-timeline">${d.memory.slice().reverse().map(x=>`<div class="ceo-event"><time>${dateLabel(x.createdAt)}</time><h3>${escape(x.title)}</h3><p>${escape(x.summary)}</p>${x.type==='review'?button('Otevřít historické review','open-review',false,`data-id="${escape(x.refId)}"`):''}</div>`).join('')}</div>`:'<div class="ceo-empty"><h2>První týden začne psát historii.</h2><p>Uzavři review nebo ulož rozhodnutí. Za týden porovnáš výsledek s původním očekáváním.</p></div>'}<div id="ceo-review-detail"></div></div>`;}

  function settingsView(d){
    const s=settings(), current=A.buildInput(S,{asOf:today(),period:period==='previous'?'previous':'week',planJob:z=>B.planJob(z,S.nastaveni)}),week=current.period.start;
    const w=d.weeklyInputs.find(x=>x.week===week)||{};
    const z=S.zakazky.find(x=>x.id===selectedJob)||S.zakazky[0];if(z)selectedJob=z.id;
    const f=z?.founder||{};
    const thresholds=[['targetGrossMargin','Cílová hrubá marže',true],['minGrossMargin','Minimální hrubá marže',true],['minGpPerCrewDay','Min. GP / člověkoden (Kč)'],['targetQuoteWinRate','Cílová konverze nabídek',true],['minQuoteWinRate','Minimální konverze nabídek',true],['targetUtilization','Cílové vytížení',true],['lowUtilization','Nízké vytížení pod',true],['highUtilization','Vysoké vytížení nad',true],['maxBacklogDays','Max. backlog (pracovní dny)'],['lowBacklogDays','Nízký backlog (pracovní dny)'],['targetQualifiedLeads','Cílové poptávky / týden'],['minCriticalRunway','Kritická runway pod (týdny)'],['minRunway','Minimální runway (týdny)'],['healthyRunway','Zdravá runway nad (týdny)'],['significantOverdueLiabilities','Významné závazky po splatnosti (Kč)'],['maxCostVariance','Max. odchylka nákladů',true],['maxLateStartRate','Max. podíl pozdních nástupů',true],['maxReworkRate','Max. podíl oprav',true],['minConsecutiveLosses','Ztrátové zakázky v řadě'],['founderDelegationRatio','Delegovatelný podíl času',true],['minimumJobValue','Minimální hodnota zakázky (Kč)'],['experimentBudget','Výchozí budget experimentu (Kč)'],['minimumExperimentLeads','Práh experimentu (poptávky)']];
    return `<div class="ceo-note neutral"><b>Jeden zdroj pravdy.</b> Zakázky, klienty ani platby sem nepřepisuj. Doplňují se pouze údaje, které kalkulačka dosud nezná. Founder OS má vlastní úložiště a vlastní zálohu. Data kalkulačky pouze čte; další fakta eviduje samostatně podle ID zakázky.</div><div class="ceo-grid"><div><div class="ceo-card"><h2>Dostupnost dat</h2>${row('Uložené zakázky',number(S.zakazky.length))}${row('Dokončené a prokazatelně zaplacené',number(input.completedPaidJobs))}${issueNote()}${button('Upravit bankovní zůstatek a rezervy','cash')}</div><div class="ceo-card"><h2>Týdenní kapacita a poptávky</h2><p class="ceo-muted">Kalkulačka nevede samostatnou evidenci kvalifikovaných leadů ani dostupnosti celé firmy. Tyto údaje stačí doplnit jednou týdně.</p><form id="ceo-week-form" class="ceo-form">${field('Týden začínající pondělím','week',week,'date','','required')}${field('Kvalifikované poptávky','qualifiedLeads',w.qualifiedLeads,'number','Počet skutečných poptávek v tomto týdnu.','min="0" step="1"')}${field('Dostupné osobohodiny celé firmy','availableHours',w.availableHours,'number','Součet dostupnosti všech pracovníků na celý týden.','min="0" step="0.5"')}${field('Celkový čas zakladatele (h)','founderHours',w.founderHours,'number','','min="0" step="0.5"')}${field('Z toho delegovatelný čas (h)','founderDelegatableHours',w.founderDelegatableHours,'number','','min="0" step="0.5"')}${select('Nedostatek lidí blokuje práci?','understaffed',w.understaffed==null?'':String(w.understaffed),[['','Nevím'],['false','Ne'],['true','Ano']])}<div class="ceo-full"><button class="b prim" type="submit">Uložit týdenní vstup</button></div></form><p class="ceo-muted">Ve fázi prvních zakázek je fyzická práce zakladatele také zdrojem zkušeností.</p>${d.weeklyInputs.length?`<div class="ceo-tools">${d.weeklyInputs.slice().sort((a,b)=>b.week.localeCompare(a.week)).slice(0,13).map(x=>button(dateLabel(x.week),'load-week',false,`data-id="${x.week}"`)).join('')}</div>`:''}</div>
      <div class="ceo-card"><h2>Doplnění existující zakázky</h2><p class="ceo-muted">Skutečné náklady se nezaměňují s kalkulací. Datum posledního uložení není datum realizace. Údaje níže se ukládají pouze ve Founder OS a odkazují na ID zakázky. Kalkulačka se nemění.</p>${z?`<label class="ceo-field">Zakázka<select id="ceo-job-select">${S.zakazky.map(j=>`<option value="${escape(j.id)}" ${j.id===selectedJob?'selected':''}>${escape(j.nazev)} · ${escape(j.status)}</option>`).join('')}</select></label><form id="ceo-job-form" class="ceo-form" style="margin-top:15px">${field('Přijetí kvalifikované poptávky','leadDate',f.leadDate,'date','',`max="${today()}"`)}${field('Nabídka skutečně odeslána','quoteDate',f.quoteDate,'date','',`max="${today()}"`)}${field('Zakázka získána','wonDate',f.wonDate,'date','',`max="${today()}"`)}${field('Skutečné dokončení','completedDate',f.completedDate,'date','',`max="${today()}"`)}${field('Skutečné přímé náklady (Kč bez DPH)','actualDirectCosts',f.actualDirectCosts,'number','Včetně práce, dopravy, odpadů a subdodávek. Prázdné = neznámé.','min="0" step="0.01"')}${field('Skutečné tržby (Kč bez DPH)','actualRevenue',f.actualRevenue,'number','Prázdné = sjednaná cena kalkulace, označená jako odhad.','min="0" step="0.01"')}${select('Nástup proběhl včas?','onTimeStart',f.onTimeStart==null?'':String(f.onTimeStart),[['','Nevím'],['true','Ano'],['false','Ne']])}${field('Čas oprav / předělávek (h)','reworkHours',f.reworkHours,'number','','min="0" step="0.5"')}<div class="ceo-full"><button type="submit" class="b prim">Uložit doplnění ve Founder OS</button></div></form>`:'<p class="ceo-muted">Zatím nemáš žádnou uloženou zakázku.</p>'+button('Otevřít kalkulaci','open-calculator')}</div></div>
      <aside><div class="ceo-card"><h2>Firma a pravidla</h2><form id="ceo-settings-form" class="ceo-form">${field('Minimální provozní rezerva (Kč)','operatingReserve',s.operatingReserve,'number','','min="0" step="0.01" required')}${field('Standardní člověkoden (h)','standardWorkdayHours',s.standardWorkdayHours,'number','GP / crew-day používá osobohodiny dělené tímto počtem hodin.','min="1" max="24" step="0.5" required')}${field('Počet samostatných part','crews',d.team.crews,'number','','min="1" step="1" required')}${field('Počet provozoven','locations',d.team.locations,'number','','min="1" step="1" required')}${select('Tým realizuje i bez zakladatele','independent',String(d.team.independent),[['false','Ne'],['true','Ano']])}${select('Celostátní firma s vedením','national',String(d.team.national),[['false','Ne'],['true','Ano']])}<details class="ceo-details ceo-full"><summary>Prahy pro diagnózu a cíle</summary><div class="ceo-form">${thresholds.map(([key,label,pct])=>field(label+(pct?' (%)':''),key,pct?Math.round(s[key]*10000)/100:s[key],'number','',`min="0" ${pct?'max="100"':''} step="any" required`)).join('')}</div></details><div class="ceo-full"><button type="submit" class="b prim">Uložit pravidla</button></div></form><p class="ceo-muted">Výchozí prahy jsou pracovní hypotézy. Uprav je podle ekonomiky vaší firmy.</p></div><div class="ceo-card"><h2>Výpočty a interpretace</h2><p>Finanční matematiku i výběr úzkého hrdla počítají pravidla. ${cloudMode?'Aplikace funguje bez AI. Vlastní záznamy a připojený přehled zakázek se ukládají do samostatného společného úložiště Founder OS.':'Aplikace funguje bez AI a data zůstávají v tomto prohlížeči.'}</p><p class="ceo-muted">Volitelný AI poskytovatel může přijímat pouze strukturovaný stav a vracet validované vysvětlení. Připojený poskytovatel zde zatím není.</p>${button('Exportovat strukturovaný stav','export-state')}${button('Export zálohy Founder OS','backup')+button('Obnovit zálohu Founder OS','restore-own')}</div></aside></div>`;
  }

  function memory(type,refId,title,summary){data().memory.push({id:id(),type,refId,title,summary,createdAt:new Date().toISOString()});}
  function downloadJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function readDecision(form){const x={};['title','type','evidence','targetConstraint','metric','cheaperTest'].forEach(k=>x[k]=textValue(form,k));['oneTimeCost','monthlyCost','founderHours','monthlyRevenueImpact','monthlySavings','capacityHours','feedbackDays','reversibility'].forEach(k=>x[k]=numeric(form,k));return x;}
  root.addEventListener('input',event=>{const form=event.target.closest('form');if(form)formDirty=true;if(form?.id==='ceo-decision-form'){decisionDraft=readDecision(form);decisionResult=null;}if(form?.id==='ceo-review-form'){reviewDraft=Object.fromEntries(new FormData(form));}});
  root.addEventListener('change',event=>{
    if(['ceo-period','ceo-job-select'].includes(event.target.id)&&formDirty){if(!confirm('Opustit rozepsaný formulář bez uložení?')){event.target.value=event.target.id==='ceo-period'?period:selectedJob;return;}formDirty=false;}
    if(event.target.id==='ceo-period'){period=event.target.value;decisionResult=null;render();}
    if(event.target.id==='ceo-job-select'){selectedJob=event.target.value;render();}
  });
  root.addEventListener('click',async event=>{
    const b=event.target.closest('[data-ceo]');if(!b)return;const action=b.dataset.ceo;
    if(saving){notify('Probíhá ukládání. Chvilku počkej.');return;}
    if(['state','constraint','cash','decisions','review','settings'].includes(action)){if(formDirty&&!confirm('Opustit rozepsaný formulář bez uložení?'))return;formDirty=false;view=action;render();return;}
    if(cloudMode&&['cloud-refresh','cloud-attach','cloud-detach','cloud-share','cloud-draft'].includes(action)){
      try{
        if(action==='cloud-draft'){const draft=bridge.exportDraft();if(!draft)throw new Error('Není tu neuložený návrh.');downloadJSON(draft,'founder-os-neulozeny-navrh-'+today()+'.json');return;}
        if(action==='cloud-share'){const link=bridge.viewerLink();try{await navigator.clipboard.writeText(link);notify('Odkaz pro náhled je zkopírovaný. Pošli jej parťákovi.');}catch(_){window.prompt('Zkopíruj tento odkaz a pošli jej parťákovi:',link);}return;}
        if(action==='cloud-refresh'){if(formDirty&&!confirm('Načíst aktuální údaje? Rozepsaný formulář tím opustíš. Pokud předchozí uložení selhalo, můžeš jeho návrh nejdřív zálohovat.'))return;await bridge.refresh();formDirty=false;decisionResult=null;}
        if(['cloud-attach','cloud-detach'].includes(action)&&formDirty){if(!confirm('Opustit rozepsaný formulář bez uložení?'))return;formDirty=false;}
        if(action==='cloud-attach'){await bridge.attachCalculator();}
        if(action==='cloud-detach')bridge.detachCalculator();
        render();notify('Sdílené údaje jsou aktuální.');
      }catch(error){notify(error.message,true);}return;
    }
    if(cloudMode&&connection.role!=='owner'&&['import-source','restore-own','use-shared','save-decision','remove-flow'].includes(action)){notify('Tento přístup je pouze pro čtení.',true);return;}
    if(action==='open-calculator'){window.open('https://brzotomas.github.io/kalkulacka/','_blank','noopener');return;}
    if(action==='backup'){downloadJSON(bridge.exportOwn(),'founder-os-zaloha-'+today()+'.json');notify('Vlastní záloha Founder OS byla exportována.');return;}
    if(action==='import-source'){if(formDirty&&!confirm('Po načtení zakázek opustíš rozepsaný formulář bez uložení. Pokračovat?'))return;document.getElementById('ceo-source-file').click();return;}
    if(action==='restore-own'){document.getElementById('ceo-own-file').click();return;}
    if(action==='use-shared'){bridge.useShared();render();return;}
    if(action==='export-state'){refresh();downloadJSON({version:1,input,state,settings:settings()},'founder-os-stav-'+today()+'.json');notify('Strukturovaný stav byl exportován.');return;}
    if(action==='save-decision'){
      if(!decisionResult){notify('Formulář se změnil. Nejprve znovu posuď rozhodnutí.',true);return;}
      refresh();const result=E.evaluateDecision(decisionDraft,state,settings());const record={...clone(decisionDraft),id:id(),createdAt:new Date().toISOString(),result:clone(result),snapshot:clone(state),settings:settings()};
      if(await persist(()=>{data().decisions.push(record);memory('decision',record.id,record.title,verdicts[result.verdict]||result.verdict);})){decisionResult=null;decisionDraft={};render();notify('Rozhodnutí a jeho tehdejší hodnocení jsou uložené.');}return;
    }
    if(action==='remove-flow'){if(await persist(()=>data().forecastItems=data().forecastItems.filter(x=>x.id!==b.dataset.id))){render();notify('Položka odebrána z plánu.');}return;}
    if(action==='load-week'){const w=data().weeklyInputs.find(x=>x.week===b.dataset.id);const form=root.querySelector('#ceo-week-form');if(w&&form)Object.entries(w).forEach(([k,v])=>{if(form.elements.namedItem(k))form.elements.namedItem(k).value=v??'';});form?.scrollIntoView({block:'center'});return;}
    if(action==='open-review'){const r=data().reviews.find(x=>x.id===b.dataset.id);if(!r)return;const snap=data().snapshots.find(x=>x.id===r.snapshotId);const detail=document.getElementById('ceo-review-detail');detail.innerHTML=`<div class="ceo-card"><h2>Review z ${dateLabel(r.createdAt)}</h2><p><b>Cíl:</b> ${escape(r.plan.objective)}</p>${list(r.plan.actions)}<h3>Zkušenosti z týdne</h3>${Object.entries(r.answers).map(([k,v])=>`<p><b>${escape(({wentWrong:'Co se pokazilo',lostWhy:'Proč jsme prohráli',blockedBy:'Co nás brzdilo',surprise:'Překvapení',tested:'Co jsme testovali',nextWeek:'Další týden'})[k]||k)}:</b> ${escape(v)}</p>`).join('')}<h3>Co odložit</h3>${list(r.plan.avoid)}<details class="ceo-details"><summary>Neměnný snímek výpočtů</summary><pre>${escape(JSON.stringify(snap,null,2))}</pre></details></div>`;detail.scrollIntoView({block:'start'});}
  });
  root.addEventListener('submit',async event=>{
    const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();
    if(cloudMode&&connection.role!=='owner'){notify('Tento přístup je pouze pro čtení.',true);return;}
    if(!form.reportValidity())return;
    try{
      if(form.id==='ceo-cash-form'){
        const c={asOf:textValue(form,'asOf')};['bankCash','taxReserve','payrollReserve','committedPayables','customerAdvanceReserve','weeklyBurn','overdueLiabilities'].forEach(k=>c[k]=numeric(form,k));const unfunded=textValue(form,'unfundedWork');c.unfundedWork=unfunded===''?null:unfunded==='true';
        if(await persist(()=>data().cash=c)){render();notify('Cash snímek uložen a přepočítán.');}
      }else if(form.id==='ceo-week-form'){
        const week=textValue(form,'week');if(new Date(week+'T12:00:00').getDay()!==1)throw new Error('Zvol pondělí daného týdne.');
        const w={week};['qualifiedLeads','availableHours','founderHours','founderDelegatableHours'].forEach(k=>w[k]=numeric(form,k));const u=textValue(form,'understaffed');w.understaffed=u===''?null:u==='true';
        if(w.founderHours!=null&&w.founderDelegatableHours>w.founderHours)throw new Error('Delegovatelný čas nemůže být vyšší než celkový čas.');
        if(await persist(()=>{const ix=data().weeklyInputs.findIndex(x=>x.week===week);if(ix<0)data().weeklyInputs.push(w);else data().weeklyInputs[ix]=w;})){render();notify('Týdenní údaje uložené.');}
      }else if(form.id==='ceo-job-form'){
        const f={};['leadDate','quoteDate','wonDate','completedDate'].forEach(k=>f[k]=textValue(form,k));['actualDirectCosts','actualRevenue','reworkHours'].forEach(k=>f[k]=numeric(form,k));const onTime=textValue(form,'onTimeStart');f.onTimeStart=onTime===''?null:onTime==='true';
        const dates=['leadDate','quoteDate','wonDate','completedDate'].map(k=>f[k]).filter(Boolean);for(let i=1;i<dates.length;i++)if(dates[i]<dates[i-1])throw new Error('Data zakázky musí jít v pořadí poptávka → nabídka → získání → dokončení.');
        if(await persist(()=>{const z=S.zakazky.find(x=>x.id===selectedJob);if(!z)throw new Error('Zakázka nebyla nalezena.');data().jobFacts[z.id]={...(data().jobFacts[z.id]||{}),...f};})){render();notify('Doplnění uloženo ve Founder OS. Zakázka v kalkulačce nebyla změněna.');}
      }else if(form.id==='ceo-settings-form'){
        const keys=Object.keys(E.defaults()),s={...settings()};const ratios=['targetGrossMargin','minGrossMargin','targetQuoteWinRate','minQuoteWinRate','targetUtilization','lowUtilization','highUtilization','maxCostVariance','maxLateStartRate','maxReworkRate','founderDelegationRatio'];
        keys.forEach(k=>{if(form.elements.namedItem(k))s[k]=numeric(form,k,false)/(ratios.includes(k)?100:1);});
        if(!(s.minGrossMargin<=s.targetGrossMargin&&s.minQuoteWinRate<=s.targetQuoteWinRate&&s.lowUtilization<s.highUtilization&&s.lowUtilization<=s.targetUtilization&&s.targetUtilization<=s.highUtilization&&s.minCriticalRunway<s.minRunway&&s.minRunway<s.healthyRunway&&s.lowBacklogDays<s.maxBacklogDays))throw new Error('Zkontroluj pořadí prahů: minimum musí být pod cílem a nízká hodnota pod vysokou.');
        const team={crews:numeric(form,'crews',false),locations:numeric(form,'locations',false),independent:textValue(form,'independent')==='true',national:textValue(form,'national')==='true'};
        if(await persist(()=>{data().settings=s;data().team=team;})){render();notify('Pravidla uložená. Historické snímky zůstaly zachované.');}
      }else if(form.id==='ceo-forecast-form'){
        const x={id:id(),label:textValue(form,'label'),date:textValue(form,'date'),amount:numeric(form,'amount',false),direction:textValue(form,'direction'),layer:textValue(form,'layer'),category:textValue(form,'category'),probability:textValue(form,'layer')==='committed'?1:numeric(form,'probability',false)/100};
        if(await persist(()=>data().forecastItems.push(x))){render();notify('Plánovaná platba přidána.');}
      }else if(form.id==='ceo-decision-form'){
        decisionDraft=readDecision(form);refresh();decisionResult=E.evaluateDecision(decisionDraft,state,settings());render();notify('Rozhodnutí posouzeno. Výsledek ještě není uložený.');
      }else if(form.id==='ceo-review-form'){
        const answers=Object.fromEntries(new FormData(form));refresh();const snapshot={id:id(),createdAt:new Date().toISOString(),input:clone(input),state:clone(state),settings:settings()};const r={id:id(),createdAt:snapshot.createdAt,snapshotId:snapshot.id,answers,plan:clone(plan)};
        if(await persist(()=>{data().snapshots.push(snapshot);data().reviews.push(r);memory('review',r.id,'Týdenní CEO review',plan.objective);})){reviewDraft={};render();notify('Review a neměnný snímek firmy uložené.');}
      }else if(form.id==='ceo-experiment-form'){
        if(data().experiments.some(x=>x.status==='ACTIVE'))throw new Error('Nejdřív vyhodnoť probíhající experiment.');
        const x={id:id(),createdAt:new Date().toISOString(),status:'ACTIVE',constraint:state.primary?.key||null};['hypothesis','action','owner','startDate','endDate','metric','comparison','conditions'].forEach(k=>x[k]=textValue(form,k));['budget','successThreshold'].forEach(k=>x[k]=numeric(form,k,false));if(x.endDate<x.startDate)throw new Error('Konec experimentu nesmí být před začátkem.');
        if(await persist(()=>{data().experiments.push(x);memory('experiment',x.id,'Zahájen experiment',x.hypothesis);})){render();notify('Experiment zahájen.');}
      }else if(form.classList.contains('ceo-result-form')){
        const result=numeric(form,'result'),decision=textValue(form,'decision'),conditionValue=textValue(form,'conditionsMet'),conditionsMet=conditionValue===''?null:conditionValue==='true';
        if(await persist(()=>{const x=data().experiments.find(x=>x.id===form.dataset.id);if(!x||x.status!=='ACTIVE')throw new Error('Experiment už je uzavřený.');x.result=result;x.decision=decision;x.conditionsMet=conditionsMet;x.status=E.evaluateExperiment({result,comparison:x.comparison,successThreshold:x.successThreshold,conditionsMet});x.completedAt=new Date().toISOString();memory('outcome',x.id,'Výsledek experimentu: '+({VALIDATED:'ověřeno',INVALIDATED:'vyvráceno',INCONCLUSIVE:'neprůkazné'})[x.status],x.hypothesis+' — '+decision);})){render();notify('Výsledek a rozhodnutí uložené do business memory.');}
      }
    }catch(error){notify(error.message||'Údaje se nepodařilo zpracovat.',true);}
  });
  document.getElementById('ceo-source-file').addEventListener('change',async event=>{
    const file=event.target.files[0];if(!file)return;
    try{await bridge.importSource(JSON.parse(await file.text()));formDirty=false;decisionResult=null;render();notify(cloudMode?'Zakázky jsou sdílené. Kalkulačka nebyla změněna.':'Záloha načtena jen pro čtení. Původní data kalkulačky nebyla změněna.');}
    catch(error){notify(error.message,true);}event.target.value='';
  });
  document.getElementById('ceo-own-file').addEventListener('change',async event=>{
    const file=event.target.files[0];if(!file)return;
    try{const value=JSON.parse(await file.text());if(!confirm('Nahradit data Founder OS touto zálohou? Kalkulačka se nemění. Nejprve si můžeš exportovat současnou zálohu Founder OS.'))return;await bridge.importOwn(value);formDirty=false;render();notify('Obnovena pouze vlastní data Founder OS.');}
    catch(error){notify(error.message,true);}finally{event.target.value='';}
  });
  if(!cloudMode)window.addEventListener('storage',event=>{if(event.key===B.SOURCE_KEY)notify('Kalkulačka má nová data. Načtou se při dalším přepnutí sekce.');if(event.key===B.OWNER_KEY)notify('Founder OS změnila jiná karta. Obnov stránku před další úpravou.',true);});
  render();
  if(cloudMode)setInterval(async()=>{
    if(polling||document.hidden)return;polling=true;
    try{
      const sourceChanged=await bridge.syncCalculator();
      const result=await bridge.refresh({apply:()=>!formDirty&&!saving});
      if(!formDirty&&(result.changed||sourceChanged)){decisionResult=null;render();}
      const info=bridge.read(),status=document.getElementById('ceo-sync-status');
      if(status)status.textContent=bridge.exportDraft()?'Poslední změna není potvrzená. Návrh můžeš zálohovat tlačítkem nahoře.':info.remoteChanged?'Jsou dostupná novější data. Před dalším uložením použij Načíst aktuální.':'Online · kontrola '+new Date().toLocaleTimeString('cs-CZ')+' · zakázky '+(info.sourceSavedAt?new Date(info.sourceSavedAt).toLocaleString('cs-CZ'):'zatím nepřipojené');
    }catch(error){const status=document.getElementById('ceo-sync-status');if(status)status.textContent='Spojení přerušené. Zobrazená data mohou být starší. '+error.message;}
    finally{polling=false;}
  },5000);
})();
